# Try anti-diagonal reflection: (i, j) -> (7-j, 7-i)
def anti_diagonal_reflect(grid):
    n = len(grid)
    result = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] != 0:
                result[7-j][7-i] = grid[i][j]
    return result

